H.background();
const v = H.plot2d({ xMin: 0, xMax: 6, yMin: 0, yMax: 12 });
v.grid(); v.axes();
const C = P.C * 1e-6;          // capacitance, microfarads -> farads
const V0 = P.V0;              // supply voltage, volts
const R = P.R * 1e3;         // resistance, kilo-ohms -> ohms
const tau = R * C;          // time constant (s)
// charging curve V(T) = V0 (1 - e^{-T/tau}); plot vs time on x-axis (seconds)
const Vof = (T) => V0 * (1 - Math.exp(-T / Math.max(1e-9, tau)));
v.fn(x => Vof(x), { color: H.colors.accent, width: 3 });
// supply (asymptote) and one-time-constant marker
v.line(0, V0, 6, V0, { color: H.colors.violet, width: 1.5, dash: [5, 5] });
v.text("V₀ = " + V0.toFixed(1) + " V", 4.2, V0 + 0.5, { color: H.colors.violet, size: 12 });
if (tau <= 6) {
  v.line(tau, 0, tau, Vof(tau), { color: H.colors.sub, width: 1, dash: [3, 3] });
  v.dot(tau, Vof(tau), { r: 4, fill: H.colors.sub });
  v.text("τ = RC", tau + 0.1, Vof(tau) - 0.6, { color: H.colors.sub, size: 11 });
}
// charging dot loops: time sweeps 0..6 s then resets (capacitor charges again)
const T = (t * 0.6) % 6;
const Vnow = Vof(T);
const Unow = 0.5 * C * Vnow * Vnow;        // joules
const Qnow = C * Vnow;                      // coulombs
v.dot(T, Vnow, { r: 6, fill: H.colors.warn });
// energy bar (U grows with V^2) on the right edge, full at U_max = 1/2 C V0^2
const Umax = 0.5 * C * V0 * V0;
const barFrac = Umax > 0 ? H.clamp(Unow / Umax, 0, 1) : 0;
v.rect(5.4, 0, 0.45, 11 * barFrac, { fill: H.colors.good });
v.rect(5.4, 0, 0.45, 11, { stroke: H.colors.axis, width: 1 });
v.text("U", 5.62, 11.4, { color: H.colors.good, size: 12, align: "center", weight: 700 });
H.text("Energy stored in a capacitor:  U = ½·C·V²", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("V = " + Vnow.toFixed(2) + " V   Q = " + (Qnow * 1e6).toFixed(1) + " µC   U = " + (Unow * 1e6).toFixed(1) + " µJ   (τ = " + tau.toFixed(2) + " s)", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "V(t) charging", color: H.colors.accent }, { label: "stored U", color: H.colors.good }], H.W - 170, 28);
